package com.company.platform.order.infrastructure;
import org.springframework.security.core.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Component;import java.util.UUID;
@Component public class SecurityTenantContextProvider implements TenantContextProvider{public UUID currentTenantId(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new IllegalStateException("authenticated tenant context required");if(a instanceof JwtAuthenticationToken j){Object v=j.getToken().getClaims().getOrDefault("tenant_id",j.getToken().getClaims().get("tenantId"));if(v!=null)return UUID.fromString(v.toString());}throw new IllegalStateException("tenant_id claim required");}}
